+def test_decimal_serialization_schema_matches_scientific_notation():
+    import json
+    import re
+
+    class MyModel(BaseModel):
+        value: Decimal | None
+
+    schema = MyModel.model_json_schema(mode='serialization')
+    string_schema = next(
+        v for v in schema['properties']['value']['anyOf'] if v.get('type') == 'string'
+    )
+    pattern = re.compile(string_schema['pattern'])
+
+    # pydantic-core serializes this Decimal in scientific notation ("1E-7"),
+    # which must still match the schema's own pattern.
+    m = MyModel(value=Decimal('0.0000001'))
+    serialized = json.loads(m.model_dump_json())['value']
+    assert serialized == '1E-7'
+    assert pattern.match(serialized) is not None
+
+    # A few more values that stringify to scientific notation.
+    for raw in ['1E-7', '1E+20', '-2.5E-10']:
+        assert pattern.match(str(Decimal(raw))) is not None
+
+
